Prediction predict(const Model &model, const Vector &values,
                   const std::array<std::array<double, 5>, 5> &costs) {
    Prediction out;
    const int classes = model.stats.classes, size = model.stats.size;
    std::array<double, 5> scores{};
    const double h = size * std::log(2 * std::acos(-1.0)) / 2;
    for (int k = 0; k < classes; ++k) {
        Vector difference{};
        for (int j = 0; j < size; ++j)
            difference[j] = values[model.features[j]] - model.stats.means[k][j];
        out.distance[k] = quadratic(model.lower[k], difference, size);
        scores[k] = std::log(model.stats.priors[k]) - h - model.log_det[k] / 2 - out.distance[k] / 2;
        if (scores[k] > scores[out.predicted])
            out.predicted = k;
    }
    const double maximum = scores[out.predicted];
    double sum = 0;
    for (int k = 0; k < classes; ++k) {
        out.posterior[k] = std::exp(scores[k] - maximum);
        sum += out.posterior[k];
    }
    for (int k = 0; k < classes; ++k) {
        out.posterior[k] /= sum;
        out.log_posterior[k] = (scores[k] - maximum) - std::log(sum);
    }
    out.confidence = out.posterior[out.predicted];
    double best = 0;
    for (int b = 0; b < classes; ++b) {
        double risk = 0;
        for (int k = 0; k < classes; ++k)
            risk += out.posterior[k] * costs[k][b];
        if (b == 0 || risk < best) {
            best = risk;
            out.decision = b;
        }
    }
    return out;
}
Measures evaluate(const Rows &rows, const std::vector<int> &prediction, int classes) {
    Measures out;
    out.total = rows.size();
    out.classes = classes;
    for (std::size_t i = 0; i < rows.size(); ++i)
        ++out.confusion[rows[i].label][prediction[i]];
        const Measures measures = evaluate(data.test, labels[kind], classes);
        for (int i = 0; i < m; ++i)
            if (labels[kind][i] != data.test[i].label)
                part.push_back("error " + num(data.test[i].id) + " actual " +
                               data.classes[data.test[i].label] + " predicted " +
                               data.classes[labels[kind][i]] + " confidence " +
                               real(test[kind][i].confidence));
        for (double threshold : data.params.reject) {
            int count = 0, correct = 0;
            for (int i = 0; i < m; ++i)
                if (test[kind][i].confidence >= threshold) {
                    ++count;
                    correct += labels[kind][i] == data.test[i].label;
                }
            part.push_back("reject " + real(threshold) + " accepted " + num(count) + " coverage " +
                           fraction(Fraction(count, m)) + " accuracy " +
                           (count ? fraction(Fraction(correct, count)) : "-"));
        }
        double argmax = 0, decision = 0;
        int changed = 0, correct = 0;
        for (int i = 0; i < m; ++i) {
            argmax += data.costs[data.test[i].label][labels[kind][i]];
            decision += data.costs[data.test[i].label][test[kind][i].decision];
            changed += test[kind][i].decision != labels[kind][i];
            correct += test[kind][i].decision == data.test[i].label;
        }
        part.push_back(model_names[kind] + " argmax_total " + real(argmax) + " decision_total " +
                       real(decision) + " changed " + num(changed) + " decision_accuracy " +
                       fraction(Fraction(correct, m)));
    }
